// Knowledge Base FAQ Matcher for LocalMate Travel Platform
const msg = ($input.first().json.userMessage || '').toLowerCase();
const lang = $input.first().json.language || 'vi';

let response = '';

if (msg.includes('đặt tour') || msg.includes('book') || msg.includes('làm sao')) {
  response = lang === 'vi' 
    ? 'Để đặt tour: 1. Chọn danh thắng hoặc HDV bản địa trên trang chủ. 2. Chọn ngày & giờ tham quan. 3. Tiến hành xác nhận. HDV sẽ liên hệ xác nhận chuyến đi với bạn ngay lập tức!'
    : 'To book a tour: 1. Select a landmark or guide from Explore screen. 2. Choose date & time slot. 3. Confirm booking. Your guide will confirm immediately!';
} else if (msg.includes('hoàn tiền') || msg.includes('hủy') || msg.includes('refund') || msg.includes('cancel')) {
  response = lang === 'vi'
    ? 'Chính sách hủy tour: Bạn có thể hủy miễn phí trước 24 giờ so với giờ hẹn tour. Tiền đặt cọc sẽ được hoàn tự động về ví hoặc thẻ ngân hàng trong 1-3 ngày làm việc.'
    : 'Cancellation Policy: Free cancellation up to 24 hours before tour start time. Full refund will be automatically processed back to your original payment method within 1-3 business days.';
} else if (msg.includes('thanh toán') || msg.includes('pay') || msg.includes('chuyển khoản')) {
  response = lang === 'vi'
    ? 'LocalMate hỗ trợ thanh toán bảo mật bằng thẻ Visa/Mastercard (qua Stripe), ví điện tử hoặc tiền mặt trực tiếp cho HDV khi bắt đầu chuyến đi.'
    : 'LocalMate supports secure payments via Credit/Debit Cards (Stripe), e-wallets, or cash directly to your local guide upon tour start.';
} else if (msg.includes('an toàn') || msg.includes('safety') || msg.includes('bảo hiểm')) {
  response = lang === 'vi'
    ? '100% Hướng dẫn viên trên LocalMate đều đã được xác minh giấy tờ danh tính (CCCD/Hộ chiếu) và có hotline bảo vệ du khách 24/7: 1900-LOCALMATE.'
    : '100% Local Guides on LocalMate undergo strict ID verification. Our 24/7 Safety & Support hotline is always available at 1900-LOCALMATE.';
} else {
  response = lang === 'vi'
    ? `Xin chào! Tôi là Trợ lý Chatbot LocalMate (n8n Workflow). Tôi có thể giúp gì cho bạn về đặt tour, danh thắng, thanh toán hay gặp HDV bản địa?`
    : `Hello! I am your LocalMate Assistant (n8n Workflow). How can I help you today regarding bookings, places, or connecting with local guides?`;
}

return [{ json: { success: true, response, timestamp: new Date().toISOString() } }];
